// Persistent sidebar shared by every admin/unit page, so navigating between
// them never means losing your place. Pages tied to a specific unit
// ("مسودة التقرير", "عرض التقرير كاملاً") stay disabled until a unit is open.
// Full nav directory: "الرئيسية" (dashboard) is added here since it isn't
// itself a SYSTEM_PAGES entry; everything else carries its own group from
// SYSTEM_PAGES so this list is the only place a new page needs to be added.
const SIDEBAR_NAV_ITEMS = [
  { id: "dashboard", label: "لوحة المعلومات", icon: LayoutDashboard, group: "الرئيسية" },
  ...SYSTEM_PAGES,
];
const SIDEBAR_GROUPS = ["الرئيسية", "إدارة التقارير", "التقارير"];

function Sidebar({ currentView, currentUnitId, onNavigate, onLogout, isMobile, open, onClose, isAdmin }) {
  if (!isMobile && !open) return null;

  const handleNavigate = (id) => {
    onNavigate(id);
    if (isMobile) onClose();
  };

  // Unit-level staff only manage their own report — the system-wide admin
  // pages (dashboard, departments/units, indicators) stay hidden for them.
  const visibleNavItems = isAdmin ? SIDEBAR_NAV_ITEMS : SIDEBAR_NAV_ITEMS.filter((p) => p.id === "unit-report" || p.id === "full-report");

  const content = (
    <div
      style={{
        width: isMobile ? "100%" : 226,
        flexShrink: 0,
        background: "#fff",
        border: "1px solid #fff",
        boxShadow: CARD_SHADOW,
        borderRadius: isMobile ? 0 : 16,
        padding: "16px 10px",
        display: "flex",
        flexDirection: "column",
        height: isMobile ? "100vh" : "auto",
        position: isMobile ? undefined : "sticky",
        top: isMobile ? undefined : 20,
        alignSelf: isMobile ? undefined : "flex-start",
        margin: isMobile ? 0 : "20px 0 20px 20px",
        overflowY: "auto",
        boxSizing: "border-box",
      }}
    >
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8, padding: "2px 4px 14px", borderBottom: `1px solid ${BORDER}`, marginBottom: 12 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, minWidth: 0 }}>
          <div style={{ width: 28, height: 28, borderRadius: 8, background: GOLD_BG, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
            <Gauge size={14} color={GOLD} />
          </div>
          <div className="prs-title" style={{ fontSize: 13, fontWeight: 900, color: ROSE, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
            نظام توثيق الأداء
          </div>
        </div>
        <button
          type="button"
          onClick={onClose}
          title="إغلاق القائمة"
          style={{ width: 28, height: 28, borderRadius: 8, border: "none", background: "#fdfbfa", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", flexShrink: 0 }}
        >
          <X size={14} color={SUBTLE} />
        </button>
      </div>

      <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 16 }}>
        {SIDEBAR_GROUPS.map((groupName) => {
          const itemsInGroup = visibleNavItems.filter((p) => p.group === groupName);
          if (itemsInGroup.length === 0) return null;
          return (
            <div key={groupName}>
              <div style={{ fontSize: 10.5, fontWeight: 700, color: SUBTLE, padding: "0 12px 6px" }}>{groupName}</div>
              <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
                {itemsInGroup.map((page) => {
                  const Icon = page.icon;
                  const isUnitScoped = page.scope === "unit";
                  const disabled = isUnitScoped && !currentUnitId;
                  const isActive = currentView === page.id;
                  return (
                    <button
                      key={page.id}
                      type="button"
                      onClick={() => !disabled && handleNavigate(page.id)}
                      disabled={disabled}
                      title={disabled ? "افتحي وحدة أولاً من الأقسام والوحدات" : page.label}
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: 10,
                        padding: "10px 12px",
                        borderRadius: 10,
                        border: "none",
                        background: isActive ? "#fbeae8" : "transparent",
                        color: disabled ? "#c9bdb6" : isActive ? ROSE : INK,
                        fontSize: 12.5,
                        fontWeight: isActive ? 800 : 600,
                        cursor: disabled ? "not-allowed" : "pointer",
                        textAlign: "right",
                        width: "100%",
                      }}
                    >
                      <Icon size={16} strokeWidth={1.9} style={{ flexShrink: 0 }} />
                      {page.label}
                    </button>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>

      <div style={{ borderTop: `1px solid ${BORDER}`, margin: "12px 0 8px" }} />

      <button
        type="button"
        onClick={onLogout}
        title="تسجيل الخروج"
        style={{
          display: "flex",
          alignItems: "center",
          gap: 10,
          padding: "10px 12px",
          borderRadius: 10,
          border: "none",
          background: "transparent",
          color: "#c1594f",
          fontSize: 12.5,
          fontWeight: 700,
          cursor: "pointer",
          textAlign: "right",
          width: "100%",
        }}
      >
        <LogOut size={16} strokeWidth={1.9} style={{ flexShrink: 0 }} />
        تسجيل الخروج
      </button>
    </div>
  );

  if (!isMobile) return content;

  return (
    <>
      {open && <div onClick={onClose} style={{ position: "fixed", inset: 0, background: "rgba(46,36,34,0.45)", zIndex: 40 }} />}
      <div
        style={{
          position: "fixed",
          top: 0,
          bottom: 0,
          right: 0,
          zIndex: 50,
          width: 264,
          maxWidth: "82vw",
          transform: open ? "translateX(0)" : "translateX(100%)",
          transition: "transform 0.22s ease",
          boxShadow: open ? "-8px 0 24px rgba(0,0,0,0.15)" : "none",
        }}
      >
        {content}
      </div>
    </>
  );
}

// Wraps every admin/unit page with the same persistent sidebar. The page
// passed as children keeps rendering exactly as before (including its own
// GlobalStyle) — this only adds the sidebar alongside it. On mobile the
// sidebar opens as a full overlay with a dark backdrop instead of an inline
// panel, so it never fights the page for space.
function AppShell({ children, currentView, currentUnitId, onNavigate, onLogout, isAdmin = true }) {
  const isMobile = useIsMobile();
  const [sidebarOpen, setSidebarOpen] = useState(!isMobile);

  useEffect(() => {
    setSidebarOpen(!isMobile);
  }, [isMobile]);

  return (
    <div dir="rtl" style={{ display: "flex", alignItems: "flex-start", minHeight: "100vh", background: BLUSH_BG, fontFamily: "'IBM Plex Sans Arabic', sans-serif" }}>
      <GlobalStyle />
      <Sidebar
        currentView={currentView}
        currentUnitId={currentUnitId}
        onNavigate={onNavigate}
        onLogout={onLogout}
        isMobile={isMobile}
        open={sidebarOpen}
        onClose={() => setSidebarOpen(false)}
        isAdmin={isAdmin}
      />
      <div style={{ flex: 1, minWidth: 0 }}>
        {!sidebarOpen && (
          <div style={{ padding: "20px 20px 0" }}>
            <button
              type="button"
              onClick={() => setSidebarOpen(true)}
              title="فتح القائمة"
              style={{ width: 38, height: 38, borderRadius: 10, border: "1px solid #fff", boxShadow: CARD_SHADOW, background: "#fff", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}
            >
              <Menu size={17} color={INK} />
            </button>
          </div>
        )}
        {children}
      </div>
    </div>
  );
}

