// حالة المؤشر تُحسب تلقائيًا من المستهدف والمتحقق واتجاه المؤشر — لا تُدخل يدويًا.
function computeIndicatorStatus(row) {
  const target = Number(row.target);
  const actual = Number(row.actual);
  const hasData = row.target !== "" && row.target != null && row.actual !== "" && row.actual != null && !isNaN(target) && !isNaN(actual);

  if (!hasData) {
    return { key: "noData", emoji: "⚪", label: "لا توجد بيانات", color: SUBTLE, bg: GRAY_BG, ratio: null };
  }

  let ratio;
  if (row.direction && row.direction.startsWith("تنازلي")) {
    ratio = target === 0 ? (actual === 0 ? 1 : 0) : target / actual;
  } else if (row.direction && row.direction.startsWith("ضمن نطاق")) {
    ratio = target === 0 ? (actual === 0 ? 1 : 0) : 1 - Math.abs(actual - target) / Math.abs(target);
  } else {
    ratio = target === 0 ? (actual >= 0 ? 1 : 0) : actual / target;
  }

  if (ratio >= 1) return { key: "achieved", emoji: "🟢", label: "متحقق", color: GREEN, bg: GREEN_BG, ratio };
  if (ratio >= 0.9) return { key: "close", emoji: "🟡", label: "قريب من المستهدف", color: GOLD, bg: GOLD_BG, ratio };
  if (ratio >= 0.7) return { key: "needsAction", emoji: "🟠", label: "يحتاج تدخلاً", color: "#c9863a", bg: "#fdeee0", ratio };
  return { key: "struggling", emoji: "🔴", label: "متعثر", color: "#c1594f", bg: "#fbeae8", ratio };
}

// مقدار الانحراف يُحسب تلقائيًا (الفرق بين المستهدف والمتحقق، مع مراعاة اتجاه المؤشر).
function computeDeviationAmount(row) {
  const target = Number(row.target);
  const actual = Number(row.actual);
  if (isNaN(target) || isNaN(actual)) return null;
  if (row.direction && row.direction.startsWith("تنازلي")) return actual - target;
  return target - actual;
}

// خط الأساس = آخر "متحقق" مسجّل لنفس المؤشر في هذه الوحدة قبل الفترة الحالية.
function getIndicatorBaseline(indicatorHistory, name) {
  const entries = (indicatorHistory && indicatorHistory[name]) || [];
  if (entries.length === 0) return null;
  return entries[entries.length - 1].value;
}

// نقطة الربط المستقبلية: إذا صار عندنا مصدر بيانات حقيقي متصل بالنظام،
