// Merges a report row's own fields (name, actual, deviation notes) with the
// static fields that live on the indicator's definition (category, direction,
// target, ...) so status/deviation math and the read-only display both work
// off one combined view — without ever storing the definition data twice.
function resolveIndicatorRow(row, def) {
  return {
    ...row,
    category: def?.category || "",
    direction: def?.direction || "",
    nature: def?.nature || "",
    frequency: def?.frequency || "",
    unit: def?.unit || "",
    target: def?.target ?? "",
    dataSource: def?.dataSource || "",
    calculationMethod: def?.calculationMethod || "",
  };
}

