const dataStore = {
  async getDepartments() {
    try {
      const res = await storage.get(DEPARTMENTS_KEY);
      if (res && res.value) return JSON.parse(res.value);
    } catch (e) {
      // nothing saved yet
    }
    const seed = seedDepartments();
    await dataStore.saveDepartments(seed);
    return seed;
  },
  async saveDepartments(departments) {
    try {
      await storage.set(DEPARTMENTS_KEY, JSON.stringify(departments));
    } catch (e) {
      console.error("Storage error:", e);
    }
  },
  async getUnits() {
    try {
      const res = await storage.get(UNITS_KEY);
      if (res && res.value) return JSON.parse(res.value);
    } catch (e) {
      // nothing saved yet
    }
    const seed = seedUnits();
    await dataStore.saveUnits(seed);
    return seed;
  },
  async saveUnits(units) {
    try {
      await storage.set(UNITS_KEY, JSON.stringify(units));
    } catch (e) {
      console.error("Storage error:", e);
    }
  },
  // No seed here on purpose — the real approved indicators will be added
  // later through "إدارة مؤشرات الأداء" once they're finalized.
  async getIndicatorDefinitions() {
    try {
      const res = await storage.get(INDICATOR_DEFINITIONS_KEY);
      if (res && res.value) return JSON.parse(res.value);
    } catch (e) {
      // nothing saved yet
    }
    return [];
  },
  async saveIndicatorDefinitions(definitions) {
    try {
      await storage.set(INDICATOR_DEFINITIONS_KEY, JSON.stringify(definitions));
    } catch (e) {
      console.error("Storage error:", e);
    }
  },
  // No seed here on purpose — the real approved goals will be added later
  // through "إدارة الأهداف والمستهدفات" once they're finalized.
  async getGoalsDefinitions() {
    try {
      const res = await storage.get(GOALS_DEFINITIONS_KEY);
      if (res && res.value) return JSON.parse(res.value);
    } catch (e) {
      // nothing saved yet
    }
    return { strategic: [], operational: [] };
  },
  async saveGoalsDefinitions(defs) {
    try {
      await storage.set(GOALS_DEFINITIONS_KEY, JSON.stringify(defs));
    } catch (e) {
      console.error("Storage error:", e);
    }
  },
  async getReport(unitId) {
    try {
      const res = await storage.get(reportKey(unitId));
      if (res && res.value) return JSON.parse(res.value);
    } catch (e) {
      // nothing saved yet
    }
    return emptyReport();
  },
  async saveReport(unitId, report) {
    try {
      await storage.set(reportKey(unitId), JSON.stringify(report));
    } catch (e) {
      console.error("Storage error:", e);
    }
  },
  async deleteReport(unitId) {
    try {
      await storage.delete(reportKey(unitId));
    } catch (e) {
      // nothing stored for this unit yet
    }
  },
};

/* =============================== Helpers =============================== */
function computeProgress(report) {
  const total = SECTIONS.length;
  const completed = SECTIONS.filter((s) => report?.sections?.[s.id]?.status === "completed").length;
  const drafted = SECTIONS.filter((s) => report?.sections?.[s.id]?.status === "draft").length;
  return { completed, drafted, total, percent: total ? Math.round((completed / total) * 100) : 0 };
}

function statusMeta(status) {
  if (status === "completed") return { label: "مكتمل", color: GREEN, bg: GREEN_BG };
  if (status === "draft") return { label: "مسودة", color: GOLD, bg: GOLD_BG };
  return { label: "لم يبدأ", color: SUBTLE, bg: GRAY_BG };
}

function sectionStatus(report, sectionId) {
  return report?.sections?.[sectionId]?.status || "not_started";
}

function computePhaseProgress(report, phase) {
  const total = phase.sectionIds.length;
  const completed = phase.sectionIds.filter((id) => sectionStatus(report, id) === "completed").length;
  const started = phase.sectionIds.filter((id) => sectionStatus(report, id) !== "not_started").length;
  return { completed, started, total };
}

function useIsMobile(breakpoint = 860) {
  const [isMobile, setIsMobile] = useState(
    typeof window !== "undefined" && window.innerWidth ? window.innerWidth < breakpoint : false
  );
  useEffect(() => {
    if (typeof window === "undefined" || !window.addEventListener) return;
    const handler = () => setIsMobile(window.innerWidth < breakpoint);
    window.addEventListener("resize", handler);
    return () => window.removeEventListener("resize", handler);
  }, [breakpoint]);
  return isMobile;
}

/* =============================== Shared UI bits =============================== */
// Loads the Google Fonts stylesheet exactly once via a real <link> tag in
// <head> (more reliable than a CSS @import repeated inside every nested
// GlobalStyle instance, and avoids duplicate network requests).
const FONT_HREF = "https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@400;500;600;700&family=Cairo:wght@800;900&family=Almarai:wght@400;700;800&family=Amiri:wght@400;700&display=swap";
function useGoogleFonts() {
  useEffect(() => {
    if (document.querySelector(`link[href="${FONT_HREF}"]`)) return;
    const preconnect1 = document.createElement("link");
    preconnect1.rel = "preconnect";
    preconnect1.href = "https://fonts.googleapis.com";
    const preconnect2 = document.createElement("link");
    preconnect2.rel = "preconnect";
    preconnect2.href = "https://fonts.gstatic.com";
    preconnect2.crossOrigin = "anonymous";
    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = FONT_HREF;
    document.head.appendChild(preconnect1);
    document.head.appendChild(preconnect2);
    document.head.appendChild(link);
  }, []);
}

