function PillButton({ children, onClick, variant = "primary", icon: Icon, disabled, type = "button" }) {
  const styles = {
    primary: { background: ROSE, color: "#fff", border: "none" },
    ghost: { background: "#fff", color: INK, border: `1px solid ${BORDER}` },
    soft: { background: GREEN_BG, color: GREEN, border: "none" },
    danger: { background: "#fbeae8", color: "#c1594f", border: "none" },
  };
  return (
    <button
      type={type}
      onClick={onClick}
      disabled={disabled}
      className="prs-btn"
      style={{
        display: "flex",
        alignItems: "center",
        gap: 6,
        padding: "9px 14px",
        borderRadius: 10,
        fontSize: 12.5,
        fontWeight: 700,
        cursor: disabled ? "not-allowed" : "pointer",
        opacity: disabled ? 0.45 : 1,
        ...styles[variant],
      }}
    >
      {Icon && <Icon size={15} />}
      {children}
    </button>
  );
}

/* =============================== Login page =============================== */
function LoginPage({ onLogin }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();
    const match = MOCK_USERS.find((u) => u.username === username.trim() && u.password === password);
    if (!match) {
      setError("اسم المستخدم أو كلمة السر غير صحيحة");
      return;
    }
    setError("");
    onLogin(match);
  };

  return (
    <div
      dir="rtl"
      style={{
        minHeight: "100vh",
        background: BLUSH_BG,
        fontFamily: "'IBM Plex Sans Arabic', 'Segoe UI', sans-serif",
        color: INK,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        padding: 20,
      }}
    >
      <GlobalStyle />
      <div style={{ width: "100%", maxWidth: 400 }}>
        <div style={{ background: "#fff", border: "1px solid #fff", borderRadius: 22, padding: "32px 26px", boxShadow: CARD_SHADOW }}>
          <div style={{ textAlign: "center", marginBottom: 26 }}>
            <img
              src={ASSOCIATION_LOGO}
              alt="جمعية فرقان لتحفيظ القرآن الكريم بالطائف"
              style={{ width: 96, height: "auto", margin: "0 auto 14px", display: "block" }}
            />
            <div className="prs-title" style={{ fontSize: 20, fontWeight: 900 }}>
              نظام توثيق الأداء
            </div>
            <div style={{ fontSize: 12, color: SUBTLE, marginTop: 6 }}>تسجيل الدخول للمتابعة</div>
          </div>

          <form onSubmit={handleSubmit}>
            <Field label="اسم المستخدم" required>
              <div style={{ position: "relative" }}>
                <User size={16} color={SUBTLE} style={{ position: "absolute", top: "50%", right: 13, transform: "translateY(-50%)" }} />
                <input
                  style={{ ...inputStyle, paddingRight: 38 }}
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  placeholder="اسم المستخدم"
                  required
                />
              </div>
            </Field>

            <Field label="كلمة السر" required>
              <div style={{ position: "relative" }}>
                <input
                  style={{ ...inputStyle, paddingLeft: 38 }}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="كلمة السر"
                  type={showPassword ? "text" : "password"}
                  required
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  style={{ position: "absolute", top: "50%", left: 12, transform: "translateY(-50%)", background: "none", border: "none", cursor: "pointer", padding: 0, display: "flex" }}
                >
                  {showPassword ? <EyeOff size={16} color={SUBTLE} /> : <Eye size={16} color={SUBTLE} />}
                </button>
              </div>
            </Field>

            {error && (
              <div style={{ background: "#fbeae8", color: "#c1594f", fontSize: 12, borderRadius: 10, padding: "9px 12px", marginBottom: 14 }}>
                {error}
              </div>
            )}

            <button
              type="submit"
              className="prs-btn"
              style={{
                width: "100%",
                padding: "13px",
                borderRadius: 12,
                border: "none",
                background: ROSE,
                color: "#fff",
                fontSize: 14.5,
                fontWeight: 800,
                cursor: "pointer",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                gap: 8,
                boxShadow: "0 8px 18px rgba(193,123,111,0.32)",
              }}
            >
              <LogIn size={17} />
              تسجيل الدخول
            </button>
          </form>
        </div>

        <div style={{ textAlign: "center", fontSize: 11, color: SUBTLE, marginTop: 16 }}>
          بيانات تجريبية للاختبار — مديرة النظام: admin / admin123 — موظفة وحدة: unit1 / 1234
        </div>
      </div>
    </div>
  );
}

/* =============================== Admin: all reports overview =============================== */
function DepartmentUnitCard({ unit, department, report, onOpenUnit }) {
  const progress = computeProgress(report);
  const overall =
    progress.total > 0 && progress.completed === progress.total
      ? "completed"
      : progress.completed > 0 || progress.drafted > 0
      ? "draft"
      : "not_started";
  const meta = statusMeta(overall);

  return (
    <div className="prs-card" style={{ background: "#fff", border: "1px solid #fff", boxShadow: CARD_SHADOW, borderRadius: 16, padding: "16px 16px" }}>
      <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", marginBottom: 12 }}>
        <div>
          <div style={{ fontSize: 14.5, fontWeight: 800 }}>{unit.name}</div>
          {department && <div style={{ fontSize: 11, color: SUBTLE, marginTop: 2 }}>{department.name}</div>}
        </div>
        <div style={{ width: 34, height: 34, borderRadius: 10, background: "#fbeae8", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
          <Building2 size={16} color={ROSE} strokeWidth={1.9} />
        </div>
      </div>

      <div style={{ borderTop: `1px solid ${BORDER}`, paddingTop: 10, display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <button
          type="button"
          onClick={() => onOpenUnit(unit.id)}
          style={{ display: "flex", alignItems: "center", gap: 4, background: "none", border: "none", cursor: "pointer", color: ROSE, fontSize: 12.5, fontWeight: 700, padding: 0 }}
        >
          <ChevronLeft size={14} />
          التقرير
        </button>
        <span style={{ fontSize: 10.5, fontWeight: 700, color: meta.color, background: meta.bg, borderRadius: 999, padding: "3px 10px" }}>
          {meta.label}
        </span>
      </div>
    </div>
  );
}

// Landing page for unit-level staff right after login: shows only their own
// unit as a card (reusing the same DepartmentUnitCard used in the admin
