// نسبة الاستجابة تُحسب تلقائيًا من حجم العينة وعدد المستجيبات — لا تُدخل يدويًا.
function computeResponseRate(sampleSize, respondentsCount) {
  const s = Number(sampleSize);
  const r = Number(respondentsCount);
  if (!s || isNaN(s) || isNaN(r)) return null;
  return Math.round((r / s) * 100);
}

// Dropdown that lets the user add a brand-new value on the fly via "أخرى".
function ExpandableSelect({ value, onChange, baseOptions, customOptions, onAddOption, placeholder, otherLabel = "أخرى" }) {
  const [otherText, setOtherText] = useState("");
  const options = [...baseOptions, ...customOptions, otherLabel];
  const isOther = value === otherLabel;

  return (
    <div>
      <Select value={value} onChange={(e) => onChange(e.target.value)} options={options} placeholder={placeholder} />
      {isOther && (
        <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
          <input
            style={{ ...inputStyle, flex: 1 }}
            value={otherText}
            onChange={(e) => setOtherText(e.target.value)}
            placeholder="اكتبي القيمة الجديدة"
          />
          <button
            type="button"
            onClick={() => {
              const trimmed = otherText.trim();
              if (!trimmed) return;
              onAddOption(trimmed);
              setOtherText("");
            }}
            style={{ padding: "0 16px", borderRadius: 10, border: "none", background: ROSE, color: "#fff", fontSize: 13, fontWeight: 700, cursor: "pointer" }}
          >
            إضافة
          </button>
        </div>
      )}
    </div>
  );
}

function BasicSectionFields({ data, onChange, unitName, departments, units, onAddDepartment }) {
  const periodType = data.periodType || "";
  const showMonth = periodType === "شهري";
  const showTerm = periodType === "فصلي";

  const set = (key) => (value) => onChange({ ...data, [key]: value });
  const customReportingTypes = data.customReportingTypes || [];
  const customTerms = data.customTerms || [];
  const customOfficeNames = data.customOfficeNames || [];
  const activeDepartments = (departments || []).filter((d) => d.status === "active");
  const departmentOptions = activeDepartments.map((d) => d.name);
  const showOfficeName = data.reportingEntityType === "مكتب";

  // إذا اسم المكتب المُدخل يطابق اسم وحدة مسجّلة فعليًا، نعرض تلقائيًا القسم
  // أو المركز التابعة له من بيانات إدارة الأقسام والوحدات.
  const matchedOfficeUnit = (units || []).find((u) => u.name === data.officeName);
  const matchedOfficeDepartment = matchedOfficeUnit ? activeDepartments.find((d) => d.id === matchedOfficeUnit.departmentId) : null;

  // اسم الوحدة يبقى ثابتًا (كل تقرير مرتبط بوحدة واحدة فعليًا)، لكن الملاحظة
  // تحته تتغيّر تفاعليًا مع تغيّر اسم الجهة، بمقارنة القسم الفعلي للوحدة
  // (من إدارة الأقسام والوحدات) بالجهة المختارة.
  const currentUnitRecord = (units || []).find((u) => u.name === unitName);
  const currentUnitDepartment = currentUnitRecord ? activeDepartments.find((d) => d.id === currentUnitRecord.departmentId) : null;

  return (
    <div>
      <Field label="الجهة الرئيسية" required>
        <input
          style={inputStyle}
          value={data.mainEntity !== undefined ? data.mainEntity : "إدارة التعليم النسائي"}
          onChange={(e) => set("mainEntity")(e.target.value)}
          placeholder="اسم الجهة الرئيسية"
        />
      </Field>

      <Field label="الجهة التي ترفع التقرير">
        <ExpandableSelect
          value={data.reportingEntityType || ""}
          onChange={set("reportingEntityType")}
          baseOptions={REPORTING_TYPES_BASE}
          customOptions={customReportingTypes}
          placeholder="اختاري (اختياري)"
          onAddOption={(v) => {
            const next = customReportingTypes.includes(v) ? customReportingTypes : [...customReportingTypes, v];
            onChange({ ...data, customReportingTypes: next, reportingEntityType: v });
          }}
        />
      </Field>

      <Field label="اسم الجهة (القسم أو المركز)">
        <ExpandableSelect
          value={data.entityName || ""}
          onChange={set("entityName")}
          baseOptions={departmentOptions}
          customOptions={[]}
          otherLabel="إضافة قسم أو مركز جديد"
          placeholder={departmentOptions.length ? "اختاري من إدارة الأقسام والوحدات" : "لا توجد أقسام مضافة بعد"}
          onAddOption={(v) => {
            if (onAddDepartment) onAddDepartment(v);
            set("entityName")(v);
          }}
        />
      </Field>

      {showOfficeName && (
        <Field label="اسم المكتب">
          <ExpandableSelect
            value={data.officeName || ""}
            onChange={set("officeName")}
            baseOptions={OFFICE_NAMES_BASE}
            customOptions={customOfficeNames}
            placeholder="اختاري اسم المكتب"
            onAddOption={(v) => {
              const next = customOfficeNames.includes(v) ? customOfficeNames : [...customOfficeNames, v];
              onChange({ ...data, customOfficeNames: next, officeName: v });
            }}
          />
          {data.officeName && (
            <div style={{ fontSize: 11, color: SUBTLE, marginTop: 6 }}>
              القسم أو المركز التابع له:{" "}
              <strong style={{ color: matchedOfficeDepartment ? INK : SUBTLE }}>
                {matchedOfficeDepartment ? matchedOfficeDepartment.name : "لم يُسجَّل هذا المكتب بعد ضمن إدارة الأقسام والوحدات"}
              </strong>
            </div>
          )}
        </Field>
      )}

      <Field label="اسم الوحدة">
        <div style={{ ...inputStyle, background: GRAY_BG, color: SUBTLE, display: "flex", alignItems: "center" }}>{unitName}</div>
        {data.entityName && (
          <div style={{ fontSize: 11, color: currentUnitDepartment?.name === data.entityName ? GREEN : "#c1594f", marginTop: 6 }}>
            {currentUnitDepartment?.name === data.entityName
              ? `✓ هذه الوحدة تابعة لـ ${data.entityName}`
              : currentUnitDepartment
              ? `⚠ هذه الوحدة تابعة فعليًا لـ ${currentUnitDepartment.name}، وليس لـ ${data.entityName}`
              : `⚠ هذه الوحدة غير مرتبطة بأي قسم في إدارة الأقسام والوحدات حاليًا`}
          </div>
        )}
      </Field>

      <Field label="الفترة التي يغطيها التقرير">
        <Select value={periodType} onChange={(e) => set("periodType")(e.target.value)} options={PERIOD_TYPES} placeholder="اختاري (اختياري)" />
      </Field>

      <div style={{ display: "flex", gap: 12 }}>
        <div style={{ flex: 1 }}>
          <Field label="تاريخ البداية">
            <input type="date" style={inputStyle} value={data.startDate || ""} onChange={(e) => set("startDate")(e.target.value)} />
          </Field>
        </div>
        <div style={{ flex: 1 }}>
          <Field label="تاريخ النهاية">
            <input type="date" style={inputStyle} value={data.endDate || ""} onChange={(e) => set("endDate")(e.target.value)} />
          </Field>
        </div>
      </div>

      {periodType && (
        <>
          <Field label="العام الهجري">
            <Select value={data.hijriYear || ""} onChange={(e) => set("hijriYear")(e.target.value)} options={HIJRI_YEARS} />
          </Field>

          {showMonth && (
            <Field label="الشهر">
              <Select value={data.month || ""} onChange={(e) => set("month")(e.target.value)} options={MONTHS} />
            </Field>
          )}

          {showTerm && (
            <Field label="الفصل">
              <ExpandableSelect
                value={data.term || ""}
                onChange={set("term")}
                baseOptions={TERM_OPTIONS_BASE}
                customOptions={customTerms}
                placeholder="اختاري الفصل"
                onAddOption={(v) => {
                  const next = customTerms.includes(v) ? customTerms : [...customTerms, v];
                  onChange({ ...data, customTerms: next, term: v });
                }}
              />
            </Field>
          )}
        </>
      )}

      <div style={{ fontSize: 12.5, fontWeight: 800, color: ROSE, margin: "20px 0 12px", paddingBottom: 8, borderBottom: `1px solid ${BORDER}` }}>
        بيانات معدة التقرير
      </div>

      <Field label="الاسم" required>
        <input style={inputStyle} value={data.preparerName || ""} onChange={(e) => set("preparerName")(e.target.value)} placeholder="اسم معدة التقرير" />
      </Field>
      <Field label="المسمى الوظيفي" required>
        <input style={inputStyle} value={data.preparerTitle || ""} onChange={(e) => set("preparerTitle")(e.target.value)} placeholder="المسمى الوظيفي" />
      </Field>
      <Field label="اسم الرئيسة المباشرة" required>
        <input style={inputStyle} value={data.managerName || ""} onChange={(e) => set("managerName")(e.target.value)} placeholder="اسم الرئيسة المباشرة" />
      </Field>
    </div>
  );
}

