function GoalsSectionFields({ data, onChange, strategicGoals, operationalGoals }) {
  const goals = data.goals || [];
  const strategicGoalOptions = (strategicGoals && strategicGoals.length ? strategicGoals : STRATEGIC_GOALS.map((name) => ({ name }))).map((g) => g.name);
  const operationalGoalOptions = (operationalGoals && operationalGoals.length ? operationalGoals : OPERATIONAL_GOALS.map((name) => ({ name }))).map((g) => g.name);

  const addGoal = () => {
    onChange({
      ...data,
      goals: [
        ...goals,
        {
          id: `goal-${Date.now()}`,
          strategicGoal: "",
          operationalGoals: [],
        },
      ],
    });
  };
  const updateGoal = (id, patch) => {
    onChange({ ...data, goals: goals.map((g) => (g.id === id ? { ...g, ...patch } : g)) });
  };
  const removeGoal = (id) => {
    onChange({ ...data, goals: goals.filter((g) => g.id !== id) });
  };

  // Selecting/deselecting operational goal names adds or removes their
  // independent sub-records (each keeps its own level/percentage/evidence/explanation).
  const handleOperationalGoalsChange = (goal, newNames) => {
    const existing = goal.operationalGoals || [];
    const next = newNames.map(
      (name) =>
        existing.find((og) => og.name === name) || {
          id: `og-${Date.now()}-${name}`,
          name,
          level: "",
          percentage: "",
          evidenceType: "",
          evidenceAnswer: "",
          explanation: "",
        }
    );
    updateGoal(goal.id, { operationalGoals: next });
  };

  const updateOperationalGoal = (goal, ogId, patch) => {
    updateGoal(goal.id, {
      operationalGoals: (goal.operationalGoals || []).map((og) => (og.id === ogId ? { ...og, ...patch } : og)),
    });
  };

  return (
    <div>
      <div style={{ display: "flex", flexDirection: "column", gap: 18, marginBottom: 14 }}>
        {goals.map((g, i) => (
          <div key={g.id} style={{ border: `1px solid ${BORDER}`, borderRadius: 14, padding: "16px 16px", position: "relative" }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 12 }}>
              <span style={{ fontSize: 12.5, fontWeight: 800, color: ROSE }}>الهدف {i + 1}</span>
              <button
                type="button"
                onClick={() => removeGoal(g.id)}
                style={{ width: 26, height: 26, borderRadius: 8, border: "none", background: "#fbeae8", color: "#c1594f", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}
              >
                <X size={12} />
              </button>
            </div>

            <Field label="الهدف المرتبط بالخطة الاستراتيجية" required>
              <Select
                value={g.strategicGoal}
                onChange={(e) => updateGoal(g.id, { strategicGoal: e.target.value })}
                options={strategicGoalOptions}
                placeholder="اختاري الهدف الاستراتيجي"
              />
            </Field>

            <Field label="الهدف التشغيلي للوحدة" required>
              <MultiSelectDropdown
                options={operationalGoalOptions}
                values={(g.operationalGoals || []).map((og) => og.name)}
                onChange={(names) => handleOperationalGoalsChange(g, names)}
                placeholder="اختاري هدفًا أو أكثر"
              />
            </Field>

            {(g.operationalGoals || []).map((og) => (
              <div key={og.id} style={{ borderRight: `3px solid ${ROSE}`, background: "#fdfbfa", borderRadius: 10, padding: "12px 14px", marginTop: 12 }}>
                <div style={{ fontSize: 12.5, fontWeight: 800, color: INK, marginBottom: 10 }}>{og.name}</div>

                <Field label="مستوى تحقق الهدف" required>
                  <Select
                    value={og.level}
                    onChange={(e) => {
                      const level = e.target.value;
                      updateOperationalGoal(g, og.id, { level, percentage: GOAL_LEVEL_PERCENTAGE[level] ?? "" });
                    }}
                    options={GOAL_LEVELS}
                    placeholder="اختاري مستوى التحقق"
                  />
                </Field>

                <Field label="نسبة تحقق الهدف">
                  {og.level ? (
                    <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                      <div style={{ flex: 1 }}>
                        <ProgressBar percent={og.percentage || 0} color={goalLevelMeta(og.level).color} />
                      </div>
                      <span style={{ fontSize: 13, fontWeight: 800, color: goalLevelMeta(og.level).color, flexShrink: 0, minWidth: 34, textAlign: "left" }}>
                        {og.percentage}٪
                      </span>
                    </div>
                  ) : (
                    <div style={{ fontSize: 11.5, color: SUBTLE }}>تُحسب تلقائيًا بعد اختيار مستوى التحقق</div>
                  )}
                </Field>

                <Field label="دليل تحقق الهدف" required>
                  <ExpandableSelect
                    value={og.evidenceType}
                    onChange={(v) => updateOperationalGoal(g, og.id, { evidenceType: v, evidenceAnswer: "" })}
                    baseOptions={EVIDENCE_TYPES}
                    customOptions={data.customEvidenceTypes || []}
                    placeholder="اختاري نوع الدليل"
                    onAddOption={(v) => {
                      const existing = data.customEvidenceTypes || [];
                      const next = existing.includes(v) ? existing : [...existing, v];
                      onChange({
                        ...data,
                        customEvidenceTypes: next,
                        goals: goals.map((gg) =>
                          gg.id !== g.id
                            ? gg
                            : { ...gg, operationalGoals: (gg.operationalGoals || []).map((o) => (o.id === og.id ? { ...o, evidenceType: v, evidenceAnswer: "" } : o)) }
                        ),
                      });
                    }}
                  />
                </Field>

                {og.evidenceType && (
                  <Field label="إجابة الدليل" required>
                    <input
                      style={inputStyle}
                      value={og.evidenceAnswer}
                      onChange={(e) => updateOperationalGoal(g, og.id, { evidenceAnswer: e.target.value })}
                      placeholder={evidenceAnswerPlaceholder(og.evidenceType)}
                    />
                  </Field>
                )}

                <Field label="تفسير مستوى التحقق">
                  <textarea
                    style={{ ...inputStyle, minHeight: 60, resize: "vertical" }}
                    value={og.explanation || ""}
                    maxLength={300}
                    onChange={(e) => updateOperationalGoal(g, og.id, { explanation: e.target.value })}
                    placeholder="اشرحي سبب هذا المستوى من التحقق لهذا الهدف التشغيلي (٣٠٠ حرف كحد أقصى)"
                  />
                  <div style={{ fontSize: 10.5, color: SUBTLE, marginTop: 4, textAlign: "left" }}>
                    {(og.explanation || "").length} / 300
                  </div>
                </Field>
              </div>
            ))}

          </div>
        ))}
      </div>

      <PillButton variant="ghost" icon={Plus} onClick={addGoal}>
        إضافة هدف
      </PillButton>

      <div style={{ marginTop: 18 }}>
        <Field label="ملاحظات (اختياري)">
          <textarea
            style={{ ...inputStyle, minHeight: 80, resize: "vertical" }}
            value={data.notes || ""}
            onChange={(e) => onChange({ ...data, notes: e.target.value })}
            placeholder="أي ملاحظات إضافية"
          />
        </Field>
      </div>
    </div>
  );
}

// Blocks saving if any operational goal has an evidence type chosen without its answer filled in.
function validateGoalsData(data) {
  const goals = data.goals || [];
  for (const g of goals) {
    for (const og of g.operationalGoals || []) {
      if (og.evidenceType && !(og.evidenceAnswer && og.evidenceAnswer.trim())) {
        return { valid: false, message: `أدخلي إجابة دليل التحقق لهدف "${og.name}" قبل الحفظ` };
      }
    }
  }
  return { valid: true };
}

// Embedded section editor — lives inside the unit report page, no page navigation.
function SectionEditor({ unit, report, departments, units, onAddDepartment, indicatorDefinitions, onAddIndicatorDefinition, strategicGoals, operationalGoals, sectionId, onSave, onPrev, onNext, onClose }) {
  const sectionIndex = SECTIONS.findIndex((s) => s.id === sectionId);
  const section = SECTIONS[sectionIndex];
  const saved = report.sections?.[sectionId] || { status: "not_started", data: {} };
  const [data, setData] = useState(saved.data || {});
  const [completed, setCompleted] = useState(saved.status === "completed");
  const [saveStatus, setSaveStatus] = useState("");
  const [saveError, setSaveError] = useState("");

  useEffect(() => {
    const s = report.sections?.[sectionId] || { status: "not_started", data: {} };
    setData(s.data || {});
    setCompleted(s.status === "completed");
    setSaveError("");
  }, [sectionId]); // eslint-disable-line react-hooks/exhaustive-deps

  const shared = report.shared || {};
  const color = PALETTE[sectionIndex % PALETTE.length];

  // Runs section-specific validation (currently: goals evidence-answer rule)
  // before allowing a save, whether triggered by the save button or by
  // navigating to the previous/next section.
  const trySave = (status) => {
    if (sectionId === "goals") {
      const result = validateGoalsData(data);
      if (!result.valid) {
        setSaveError(result.message);
        return false;
      }
    }
    setSaveError("");
    onSave(sectionId, data, status);
    return true;
  };

  const handleSaveDraft = () => {
    const status = completed ? "completed" : "draft";
    if (trySave(status)) {
      setSaveStatus("تم الحفظ ✓");
      setTimeout(() => setSaveStatus(""), 1500);
    }
  };

  const handleToggleCompleted = () => {
    const next = !completed;
    if (trySave(next ? "completed" : "draft")) {
      setCompleted(next);
    }
  };

  const handlePrev = () => {
    if (trySave(completed ? "completed" : "draft")) onPrev();
  };
  const handleNext = () => {
    if (trySave(completed ? "completed" : "draft")) onNext();
  };

  return (
    <div style={{ background: "#fff", borderRadius: 18, padding: "20px 22px", border: "1px solid #fff", boxShadow: CARD_SHADOW }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 6 }}>
        <button
          type="button"
          onClick={onClose}
          style={{ display: "flex", alignItems: "center", gap: 5, background: "none", border: "none", color: ROSE, fontSize: 12, fontWeight: 700, cursor: "pointer", padding: 0 }}
        >
          <ArrowRight size={14} />
          رجوع إلى المراحل
        </button>
        <span style={{ fontSize: 11, color: SUBTLE }}>
          القسم {sectionIndex + 1} من {SECTIONS.length}
        </span>
      </div>

      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", margin: "14px 0 18px" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <div style={{ width: 42, height: 42, borderRadius: 12, background: color.bg, display: "flex", alignItems: "center", justifyContent: "center" }}>
            <section.icon size={20} color={color.fg} strokeWidth={1.9} />
          </div>
          <div className="prs-title" style={{ fontSize: 17, fontWeight: 800 }}>
            {section.label}
          </div>
        </div>
        <button
          type="button"
          onClick={handleToggleCompleted}
          style={{
            display: "flex",
            alignItems: "center",
            gap: 6,
            background: completed ? GREEN_BG : "#fff",
            border: `1px solid ${completed ? GREEN : BORDER}`,
            borderRadius: 999,
            padding: "6px 12px",
            cursor: "pointer",
            fontSize: 11.5,
            fontWeight: 700,
            color: completed ? GREEN : SUBTLE,
          }}
        >
          {completed ? <CheckCircle2 size={14} /> : <Circle size={14} />}
          {completed ? "مكتمل" : "تحديد كمكتمل"}
        </button>
      </div>

      {sectionId !== "basic" && (shared.periodType || shared.preparerName) && (
        <div
          style={{
            display: "flex",
            flexWrap: "wrap",
            gap: 8,
            background: "#fdfbfa",
            border: `1px solid ${BORDER}`,
            borderRadius: 12,
            padding: "10px 12px",
            marginBottom: 18,
            fontSize: 11.5,
            color: SUBTLE,
          }}
        >
          {shared.periodType && <span>الفترة: <strong style={{ color: INK }}>{shared.periodType}</strong></span>}
          {shared.hijriYear && <span>· العام: <strong style={{ color: INK }}>{shared.hijriYear}</strong></span>}
          {shared.preparerName && <span>· أعدّته: <strong style={{ color: INK }}>{shared.preparerName}</strong></span>}
        </div>
      )}

      {sectionId === "basic" ? (
        <BasicSectionFields data={data} onChange={setData} unitName={unit.name} departments={departments} units={units} onAddDepartment={onAddDepartment} />
      ) : sectionId === "kpi" ? (
        <KPISectionFields data={data} onChange={setData} indicatorDefinitions={indicatorDefinitions} indicatorHistory={report.indicatorHistory} onAddIndicatorDefinition={onAddIndicatorDefinition} />
      ) : sectionId === "goals" ? (
        <GoalsSectionFields data={data} onChange={setData} strategicGoals={strategicGoals} operationalGoals={operationalGoals} />
      ) : sectionId === "programs" ? (
        <ProgramsSectionFields data={data} onChange={setData} />
      ) : sectionId === "tools" ? (
        <ToolsSectionFields data={data} onChange={setData} />
      ) : sectionId === "analysis" ? (
        <AnalysisSectionFields data={data} onChange={setData} />
      ) : sectionId === "strengths" ? (
        <StrengthsSectionFields data={data} onChange={setData} />
      ) : sectionId === "challenges" ? (
        <ChallengesSectionFields data={data} onChange={setData} />
      ) : sectionId === "improvement" ? (
        <ImprovementSectionFields data={data} onChange={setData} />
      ) : sectionId === "initiatives" ? (
        <InitiativesSectionFields data={data} onChange={setData} />
      ) : (
        <GenericSectionFields section={section} data={data} onChange={setData} />
      )}

      {saveError && (
        <div style={{ marginTop: 16, background: "#fbeae8", color: "#c1594f", fontSize: 12.5, fontWeight: 600, borderRadius: 10, padding: "10px 14px" }}>
          {saveError}
        </div>
      )}

      <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 20, paddingTop: 16, borderTop: `1px solid ${BORDER}` }}>
        <PillButton variant="ghost" icon={ChevronRight} onClick={handlePrev} disabled={sectionIndex <= 0}>
          السابق
        </PillButton>
        <div style={{ flex: 1 }}>
          <PillButton variant="soft" icon={Save} onClick={handleSaveDraft}>
            {saveStatus || "حفظ كمسودة"}
          </PillButton>
        </div>
        <button
          type="button"
          onClick={handleNext}
          disabled={sectionIndex >= SECTIONS.length - 1}
          className="prs-btn"
          style={{
            display: "flex",
            alignItems: "center",
            gap: 4,
            padding: "9px 14px",
            borderRadius: 10,
            border: "none",
            background: sectionIndex >= SECTIONS.length - 1 ? "#f0c8bd" : ROSE,
            color: "#fff",
            fontSize: 12.5,
            fontWeight: 700,
            cursor: sectionIndex >= SECTIONS.length - 1 ? "not-allowed" : "pointer",
          }}
        >
          التالي
          <ChevronLeft size={15} />
        </button>
      </div>
    </div>
  );
}

function UnitReportPage({ unit, report, departments, units, onAddDepartment, indicatorDefinitions, onAddIndicatorDefinition, strategicGoals, operationalGoals, onSaveSection, onPreview, onFullReport, onBack }) {
  const shared = report.shared || {};
  const isMobile = useIsMobile();

  const [collapsed, setCollapsed] = useState(false);
  const [mobileSidebarOpen, setMobileSidebarOpen] = useState(false);
  const [openPhaseId, setOpenPhaseId] = useState(null);
  const [activeSectionId, setActiveSectionId] = useState(null);

  const togglePhase = (phaseId) => setOpenPhaseId((prev) => (prev === phaseId ? null : phaseId));

  const selectSection = (sectionId) => {
    const phase = PHASES.find((p) => p.sectionIds.includes(sectionId));
    setOpenPhaseId(phase ? phase.id : null);
    setActiveSectionId(sectionId);
    setMobileSidebarOpen(false);
  };

  const goToSectionByOffset = (offset) => {
    const idx = SECTIONS.findIndex((s) => s.id === activeSectionId);
    const nextIdx = idx + offset;
    if (nextIdx >= 0 && nextIdx < SECTIONS.length) {
      selectSection(SECTIONS[nextIdx].id);
    }
  };

  return (
    <div dir="rtl" style={{ minHeight: "100vh", background: BLUSH_BG, fontFamily: "'IBM Plex Sans Arabic', sans-serif", color: INK }}>
      <GlobalStyle />

      <div style={{ padding: "24px 20px 0", maxWidth: 1180, margin: "0 auto" }}>
        <TopBar
          title={unit.name}
          subtitle="التقرير الدوري"
          onBack={onBack}
          right={
            <>
              {isMobile && (
                <PillButton variant="ghost" icon={Layers} onClick={() => setMobileSidebarOpen(true)}>
                  المراحل
                </PillButton>
              )}
              <PillButton variant="ghost" icon={AlignRight} onClick={onFullReport}>
                عرض التقرير كاملاً
              </PillButton>
              <PillButton variant="ghost" icon={FileText} onClick={onPreview}>
                معاينة التقرير
              </PillButton>
            </>
          }
        />

        {(shared.periodType || shared.hijriYear) && (
          <div style={{ fontSize: 11.5, color: SUBTLE, marginBottom: 10 }}>
            {shared.periodType}
            {shared.hijriYear ? ` · ${shared.hijriYear}` : ""}
          </div>
        )}
      </div>

      <div style={{ maxWidth: 1180, margin: "0 auto", display: "flex", alignItems: "flex-start", gap: 18, padding: "0 20px 28px" }}>
        <PhaseSidebar
          report={report}
          openPhaseId={openPhaseId}
          onTogglePhase={togglePhase}
          activeSectionId={activeSectionId}
          onSelectSection={selectSection}
          collapsed={collapsed}
          onToggleCollapse={() => setCollapsed((c) => !c)}
          isMobile={isMobile}
          mobileOpen={mobileSidebarOpen}
          onCloseMobile={() => setMobileSidebarOpen(false)}
        />

        <div style={{ flex: 1, minWidth: 0, borderRadius: 16, overflow: isMobile ? "visible" : "hidden" }}>
          {activeSectionId ? (
            <SectionEditor
              unit={unit}
              report={report}
              departments={departments}
              units={units}
              onAddDepartment={onAddDepartment}
              indicatorDefinitions={indicatorDefinitions}
              onAddIndicatorDefinition={onAddIndicatorDefinition}
              strategicGoals={strategicGoals}
              operationalGoals={operationalGoals}
              sectionId={activeSectionId}
              onSave={onSaveSection}
              onPrev={() => goToSectionByOffset(-1)}
              onNext={() => goToSectionByOffset(1)}
              onClose={() => setActiveSectionId(null)}
            />
          ) : (
            <PhaseOverview report={report} openPhaseId={openPhaseId} onTogglePhase={togglePhase} onSelectSection={selectSection} />
          )}
        </div>
      </div>
    </div>
  );
}

