function toArabicDigits(n) {
  const map = ["٠", "١", "٢", "٣", "٤", "٥", "٦", "٧", "٨", "٩"];
  return String(n)
    .split("")
    .map((d) => map[+d] ?? d)
    .join("");
}

function GoalsSectionReport({ data }) {
  const goals = (data.goals || []).filter((g) => g.strategicGoal || g.operationalGoals?.length);

  if (goals.length === 0) {
    return <div style={{ fontSize: 12.5, color: SUBTLE, fontStyle: "italic" }}>لم يتم تعبئة هذا القسم بعد.</div>;
  }

  const allOps = goals.flatMap((g) => g.operationalGoals || []);
  const fullyAchieved = allOps.filter((og) => og.level === "تحقق بالكامل").length;
  const avgPct = allOps.length ? Math.round(allOps.reduce((sum, og) => sum + (Number(og.percentage) || 0), 0) / allOps.length) : 0;

  let rowCounter = 0;

  return (
    <div>
      <div style={{ display: "flex", gap: 10, marginBottom: 18 }}>
        <DocStatCard label="عدد الأهداف التشغيلية" value={allOps.length} color={ROSE} />
        <DocStatCard label="تحققت بالكامل" value={fullyAchieved} color={GREEN} />
        <DocStatCard label="متوسط نسبة التحقق" value={`${avgPct}٪`} color={GOLD} />
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
        {goals.map((g, gi) => (
          <div key={g.id || gi} className="prs-avoid-break">
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
              <span style={{ width: 22, height: 22, borderRadius: 7, background: GOLD_BG, color: GOLD, fontSize: 10.5, fontWeight: 800, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                {toArabicDigits(gi + 1)}
              </span>
              <span style={{ fontSize: 13.5, fontWeight: 800, color: INK }}>{g.strategicGoal || "—"}</span>
            </div>

            {g.operationalGoals?.length > 0 && (
              <div style={{ border: `1px solid ${BORDER}`, borderRadius: 12, overflow: "hidden" }}>
                <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
                  <thead>
                    <tr style={{ background: "#fbeae8" }}>
                      <th style={{ textAlign: "center", padding: "9px 8px", fontWeight: 800, color: ROSE_DARK, width: 34 }}>م</th>
                      <th style={{ textAlign: "right", padding: "9px 10px", fontWeight: 800, color: ROSE_DARK }}>الهدف التشغيلي</th>
                      <th style={{ textAlign: "center", padding: "9px 10px", fontWeight: 800, color: ROSE_DARK }}>مستوى التحقق</th>
                      <th style={{ textAlign: "center", padding: "9px 10px", fontWeight: 800, color: ROSE_DARK, width: 70 }}>نسبة التحقق</th>
                      <th style={{ textAlign: "center", padding: "9px 10px", fontWeight: 800, color: ROSE_DARK }}>دليل التحقق</th>
                      <th style={{ textAlign: "right", padding: "9px 10px", fontWeight: 800, color: ROSE_DARK }}>الإجابة</th>
                    </tr>
                  </thead>
                  <tbody>
                    {g.operationalGoals.map((og, oi) => {
                      rowCounter += 1;
                      const meta = goalLevelMeta(og.level);
                      const pct = Number(og.percentage) || 0;
                      const hasExplanation = og.explanation && og.explanation.trim();
                      return (
                        <React.Fragment key={og.id || oi}>
                          <tr style={{ background: oi % 2 === 1 ? "#fdfbfa" : "#fff" }}>
                            <td style={{ textAlign: "center", padding: "8px", borderTop: `1px solid ${BORDER}`, color: SUBTLE, fontWeight: 700 }}>
                              {toArabicDigits(rowCounter)}
                            </td>
                            <td style={{ padding: "8px 10px", borderTop: `1px solid ${BORDER}`, fontWeight: 600 }}>{og.name}</td>
                            <td style={{ textAlign: "center", padding: "8px 10px", borderTop: `1px solid ${BORDER}` }}>
                              {og.level ? (
                                <span style={{ fontSize: 10.5, fontWeight: 800, color: meta.color, background: meta.bg, borderRadius: 999, padding: "3px 10px", whiteSpace: "nowrap" }}>
                                  {og.level}
                                </span>
                              ) : (
                                <span style={{ color: SUBTLE }}>—</span>
                              )}
                            </td>
                            <td style={{ textAlign: "center", padding: "6px", borderTop: `1px solid ${BORDER}` }}>
                              {og.level ? <CircularProgress percent={pct} color={meta.color} size={40} /> : <span style={{ color: SUBTLE }}>—</span>}
                            </td>
                            <td style={{ textAlign: "center", padding: "8px 10px", borderTop: `1px solid ${BORDER}` }}>{og.evidenceType || <span style={{ color: SUBTLE }}>—</span>}</td>
                            <td style={{ padding: "8px 10px", borderTop: `1px solid ${BORDER}` }}>{og.evidenceAnswer || <span style={{ color: SUBTLE }}>—</span>}</td>
                          </tr>
                          {hasExplanation && (
                            <tr style={{ background: oi % 2 === 1 ? "#fdfbfa" : "#fff" }}>
                              <td colSpan={6} style={{ padding: "2px 10px 10px 10px", borderTop: "none" }}>
                                <div
                                  style={{
                                    fontSize: 11.5,
                                    lineHeight: 1.8,
                                    color: "#5c4a3f",
                                    borderRight: `2px solid ${BORDER}`,
                                    paddingRight: 10,
                                    fontStyle: "italic",
                                  }}
                                >
                                  تفسير مستوى التحقق: {og.explanation}
                                </div>
                              </td>
                            </tr>
                          )}
                        </React.Fragment>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

