export default function PeriodicReportsSystem() {
  const [currentUser, setCurrentUser] = useState(null);
  const [units, setUnits] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [indicatorDefinitions, setIndicatorDefinitions] = useState([]);
  const [goalsDefinitions, setGoalsDefinitions] = useState({ strategic: [], operational: [] });
  const [reports, setReports] = useState({});
  const [view, setView] = useState("login");
  const [currentUnitId, setCurrentUnitId] = useState(null);

  // Kept as a named wrapper (rather than passing setView directly) so the
  // sidebar's onNavigate prop stays a stable, explicit intent.
  const navigateTo = (nextView) => setView(nextView);

  const ensureReportLoaded = async (unitId, unitsList) => {
    const report = await dataStore.getReport(unitId);
    setReports((prev) => ({ ...prev, [unitId]: report }));
    return report;
  };

  const handleLogin = async (user) => {
    setCurrentUser(user);
    const loadedUnits = await dataStore.getUnits();
    setUnits(loadedUnits);
    const loadedDepartments = await dataStore.getDepartments();
    setDepartments(loadedDepartments);
    const loadedIndicatorDefinitions = await dataStore.getIndicatorDefinitions();
    setIndicatorDefinitions(loadedIndicatorDefinitions);
    const loadedGoalsDefinitions = await dataStore.getGoalsDefinitions();
    setGoalsDefinitions(loadedGoalsDefinitions);

    if (user.role === "admin") {
      const entries = await Promise.all(loadedUnits.map(async (u) => [u.id, await dataStore.getReport(u.id)]));
      setReports(Object.fromEntries(entries));
      setView("dashboard");
    } else {
      const unitId = user.unitId;
      await ensureReportLoaded(unitId, loadedUnits);
      setCurrentUnitId(unitId);
      setView("unit-home");
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setCurrentUnitId(null);
    setView("login");
  };

  const handleOpenUnit = async (unitId) => {
    if (!reports[unitId]) await ensureReportLoaded(unitId);
    setCurrentUnitId(unitId);
    setView("unit-report");
  };

  const handleSaveSection = async (sectionId, data, status) => {
    setReports((prev) => {
      const current = prev[currentUnitId] || emptyReport();
      const updatedSections = { ...current.sections, [sectionId]: { status, data, updatedAt: Date.now() } };
      let updatedShared = current.shared || {};
      if (sectionId === "basic") {
        updatedShared = {
          ...updatedShared,
          reportingEntityType: data.reportingEntityType || "",
          entityName: data.entityName || "",
          periodType: data.periodType || "",
          hijriYear: data.hijriYear || "",
          month: data.month || "",
          term: data.term || "",
          preparerName: data.preparerName || "",
          preparerTitle: data.preparerTitle || "",
          managerName: data.managerName || "",
        };
      }

      // Record this period's "المتحقق" for each indicator so the NEXT time
      // this indicator is used, "خط الأساس" can be pulled automatically.
      let updatedIndicatorHistory = current.indicatorHistory || {};
      if (sectionId === "kpi") {
        const periodLabel = [updatedShared.periodType, updatedShared.hijriYear].filter(Boolean).join(" · ");
        const nextHistory = { ...updatedIndicatorHistory };
        (data.indicators || []).forEach((row) => {
          if (!row.name || row.actual === "" || row.actual == null || isNaN(Number(row.actual))) return;
          const existing = nextHistory[row.name] || [];
          nextHistory[row.name] = [...existing, { value: Number(row.actual), period: periodLabel, savedAt: Date.now() }];
        });
        updatedIndicatorHistory = nextHistory;
      }

      const updatedReport = { sections: updatedSections, shared: updatedShared, indicatorHistory: updatedIndicatorHistory };
      dataStore.saveReport(currentUnitId, updatedReport);
      return { ...prev, [currentUnitId]: updatedReport };
    });
  };

  const handleAddDepartment = async (name) => {
    const newDept = { id: `dept-${Date.now()}`, name, status: "active", createdAt: Date.now() };
    const updated = [...departments, newDept];
    setDepartments(updated);
    await dataStore.saveDepartments(updated);
  };

  const handleRenameDepartment = async (deptId, name) => {
    const updated = departments.map((d) => (d.id === deptId ? { ...d, name } : d));
    setDepartments(updated);
    await dataStore.saveDepartments(updated);
  };

  const handleToggleDepartment = async (deptId) => {
    const updated = departments.map((d) => (d.id === deptId ? { ...d, status: d.status === "active" ? "disabled" : "active" } : d));
    setDepartments(updated);
    await dataStore.saveDepartments(updated);
  };

  const handleAddUnit = async (name, departmentId) => {
    const newUnit = { id: `unit-${Date.now()}`, name, status: "active", departmentId: departmentId || "", createdAt: Date.now() };
    const updated = [...units, newUnit];
    setUnits(updated);
    await dataStore.saveUnits(updated);
  };

  const handleRenameUnit = async (unitId, name) => {
    const updated = units.map((u) => (u.id === unitId ? { ...u, name } : u));
    setUnits(updated);
    await dataStore.saveUnits(updated);
  };

  const handleToggleUnit = async (unitId) => {
    const updated = units.map((u) => (u.id === unitId ? { ...u, status: u.status === "active" ? "disabled" : "active" } : u));
    setUnits(updated);
    await dataStore.saveUnits(updated);
  };

  const handleAssignUnitDepartment = async (unitId, departmentId) => {
    const updated = units.map((u) => (u.id === unitId ? { ...u, departmentId } : u));
    setUnits(updated);
    await dataStore.saveUnits(updated);
  };

  const handleDeleteUnit = async (unitId) => {
    const updated = units.filter((u) => u.id !== unitId);
    setUnits(updated);
    setReports((prev) => {
      const next = { ...prev };
      delete next[unitId];
      return next;
    });
    await dataStore.saveUnits(updated);
    await dataStore.deleteReport(unitId);
  };

  // Adding an indicator name from inside a report's مؤشرات الأداء section
  // (via "مؤشر جديد غير موجود في القائمة") uses this same handler, so it
  // immediately becomes available in "إدارة مؤشرات الأداء" too.
  const handleAddIndicatorDefinition = (name, extra = {}) => {
    setIndicatorDefinitions((prev) => {
      if (prev.some((d) => d.name === name)) return prev;
      const updated = [...prev, { id: `ind-${Date.now()}`, name, category: "", direction: "", unit: "", ...extra }];
      dataStore.saveIndicatorDefinitions(updated);
      return updated;
    });
  };

  const handleUpdateIndicatorDefinition = (id, patch) => {
    setIndicatorDefinitions((prev) => {
      const updated = prev.map((d) => (d.id === id ? { ...d, ...patch } : d));
      dataStore.saveIndicatorDefinitions(updated);
      return updated;
    });
  };

  const handleDeleteIndicatorDefinition = (id) => {
    setIndicatorDefinitions((prev) => {
      const updated = prev.filter((d) => d.id !== id);
      dataStore.saveIndicatorDefinitions(updated);
      return updated;
    });
  };

  const handleAddStrategicGoal = (name) => {
    setGoalsDefinitions((prev) => {
      if (prev.strategic.some((g) => g.name === name)) return prev;
      const updated = { ...prev, strategic: [...prev.strategic, { id: `sg-${Date.now()}`, name }] };
      dataStore.saveGoalsDefinitions(updated);
      return updated;
    });
  };
  const handleUpdateStrategicGoal = (id, name) => {
    setGoalsDefinitions((prev) => {
      const updated = { ...prev, strategic: prev.strategic.map((g) => (g.id === id ? { ...g, name } : g)) };
      dataStore.saveGoalsDefinitions(updated);
      return updated;
    });
  };
  const handleDeleteStrategicGoal = (id) => {
    setGoalsDefinitions((prev) => {
      const updated = { ...prev, strategic: prev.strategic.filter((g) => g.id !== id) };
      dataStore.saveGoalsDefinitions(updated);
      return updated;
    });
  };
  const handleAddOperationalGoal = (name) => {
    setGoalsDefinitions((prev) => {
      if (prev.operational.some((g) => g.name === name)) return prev;
      const updated = { ...prev, operational: [...prev.operational, { id: `og-${Date.now()}`, name }] };
      dataStore.saveGoalsDefinitions(updated);
      return updated;
    });
  };
  const handleUpdateOperationalGoal = (id, name) => {
    setGoalsDefinitions((prev) => {
      const updated = { ...prev, operational: prev.operational.map((g) => (g.id === id ? { ...g, name } : g)) };
      dataStore.saveGoalsDefinitions(updated);
      return updated;
    });
  };
  const handleDeleteOperationalGoal = (id) => {
    setGoalsDefinitions((prev) => {
      const updated = { ...prev, operational: prev.operational.filter((g) => g.id !== id) };
      dataStore.saveGoalsDefinitions(updated);
      return updated;
    });
  };

  // Loads the demo indicator set (5 indicators covering every status) plus a
  // filled-in KPI section on "وحدة الاختبارات" so the card UI can be tried
  // immediately. Testing convenience only — never runs automatically.
  const handleLoadSampleData = async () => {
    setIndicatorDefinitions((prevDefs) => {
      const mergedDefs = [...prevDefs];
      SAMPLE_INDICATOR_DEFINITIONS.forEach((def) => {
        if (!mergedDefs.some((d) => d.name === def.name)) {
          mergedDefs.push({ id: `ind-sample-${def.name}`, ...def });
        }
      });
      dataStore.saveIndicatorDefinitions(mergedDefs);
      return mergedDefs;
    });

    const targetUnit = units.find((u) => u.id === "seed-1") || units[0];
    if (!targetUnit) return;

    const existingReport = reports[targetUnit.id] || (await dataStore.getReport(targetUnit.id));
    const updatedReport = {
      ...existingReport,
      sections: {
        ...existingReport.sections,
        kpi: {
          status: "draft",
          data: { indicators: buildSampleKPIRows(), notes: existingReport.sections?.kpi?.data?.notes || "" },
          updatedAt: Date.now(),
        },
      },
      indicatorHistory: { ...existingReport.indicatorHistory, ...buildSampleIndicatorHistory() },
    };
    setReports((prev) => ({ ...prev, [targetUnit.id]: updatedReport }));
    await dataStore.saveReport(targetUnit.id, updatedReport);
  };

  const currentUnit = units.find((u) => u.id === currentUnitId);
  const currentReport = reports[currentUnitId] || emptyReport();
  const isAdmin = currentUser?.role === "admin";

  if (view === "login" || !currentUser) {
    return <LoginPage onLogin={handleLogin} />;
  }

  if (view === "dashboard") {
    return (
      <AppShell currentView={view} currentUnitId={currentUnitId} onNavigate={navigateTo} onLogout={handleLogout}>
        <DashboardPage
          units={units}
          departments={departments}
          reports={reports}
          userName={currentUser.name}
          onNavigate={navigateTo}
          onContinue={() => setView("admin-reports")}
          onLogout={handleLogout}
        />
      </AppShell>
    );
  }

  if (view === "admin-reports") {
    return (
      <AppShell currentView={view} currentUnitId={currentUnitId} onNavigate={navigateTo} onLogout={handleLogout}>
        <UnitsPage
          units={units}
          departments={departments}
          reports={reports}
          userName={currentUser.name}
          onOpenUnit={handleOpenUnit}
          onManage={() => setView("units-manage")}
          onManageIndicators={() => setView("indicators-manage")}
          onLogout={handleLogout}
        />
      </AppShell>
    );
  }

  if (view === "units-manage") {
    return (
      <AppShell currentView={view} currentUnitId={currentUnitId} onNavigate={navigateTo} onLogout={handleLogout}>
        <DepartmentsManagePage
          departments={departments}
          units={units}
          onAddDepartment={handleAddDepartment}
          onRenameDepartment={handleRenameDepartment}
          onToggleDepartment={handleToggleDepartment}
          onAddUnit={handleAddUnit}
          onRenameUnit={handleRenameUnit}
          onToggleUnit={handleToggleUnit}
          onDeleteUnit={handleDeleteUnit}
          onAssignUnitDepartment={handleAssignUnitDepartment}
          onBack={() => setView("admin-reports")}
        />
      </AppShell>
    );
  }

  if (view === "indicators-manage") {
    return (
      <AppShell currentView={view} currentUnitId={currentUnitId} onNavigate={navigateTo} onLogout={handleLogout}>
        <IndicatorsManagePage
          indicatorDefinitions={indicatorDefinitions}
          onAdd={(def) => handleAddIndicatorDefinition(def.name, def)}
          onUpdate={handleUpdateIndicatorDefinition}
          onDelete={handleDeleteIndicatorDefinition}
          onLoadSampleData={handleLoadSampleData}
          onBack={() => setView("admin-reports")}
        />
      </AppShell>
    );
  }

  if (view === "goals-manage") {
    return (
      <AppShell currentView={view} currentUnitId={currentUnitId} onNavigate={navigateTo} onLogout={handleLogout}>
        <GoalsManagePage
          goalsDefinitions={goalsDefinitions}
          onAddStrategic={handleAddStrategicGoal}
          onUpdateStrategic={handleUpdateStrategicGoal}
          onDeleteStrategic={handleDeleteStrategicGoal}
          onAddOperational={handleAddOperationalGoal}
          onUpdateOperational={handleUpdateOperationalGoal}
          onDeleteOperational={handleDeleteOperationalGoal}
          onBack={() => setView("admin-reports")}
        />
      </AppShell>
    );
  }

  if (view === "unit-home" && currentUnit) {
    return (
      <AppShell currentView={view} currentUnitId={currentUnitId} onNavigate={navigateTo} onLogout={handleLogout} isAdmin={isAdmin}>
        <MyUnitPage unit={currentUnit} report={currentReport} onOpenReport={() => setView("unit-report")} />
      </AppShell>
    );
  }

  if (view === "unit-report" && currentUnit) {
    return (
      <AppShell currentView={view} currentUnitId={currentUnitId} onNavigate={navigateTo} onLogout={handleLogout} isAdmin={isAdmin}>
        <UnitReportPage
          unit={currentUnit}
          report={currentReport}
          departments={departments}
          units={units}
          onAddDepartment={handleAddDepartment}
          indicatorDefinitions={indicatorDefinitions}
          onAddIndicatorDefinition={handleAddIndicatorDefinition}
          strategicGoals={goalsDefinitions.strategic}
          operationalGoals={goalsDefinitions.operational}
          onSaveSection={handleSaveSection}
          onPreview={() => setView("report-preview")}
          onFullReport={() => setView("full-report")}
          onBack={() => setView(isAdmin ? "admin-reports" : "unit-home")}
        />
      </AppShell>
    );
  }

  if (view === "full-report" && currentUnit) {
    return (
      <AppShell currentView={view} currentUnitId={currentUnitId} onNavigate={navigateTo} onLogout={handleLogout} isAdmin={isAdmin}>
        <FullReportPage
          unit={currentUnit}
          report={currentReport}
          departments={departments}
          units={units}
          onAddDepartment={handleAddDepartment}
          indicatorDefinitions={indicatorDefinitions}
          onAddIndicatorDefinition={handleAddIndicatorDefinition}
          strategicGoals={goalsDefinitions.strategic}
          operationalGoals={goalsDefinitions.operational}
          onSaveAll={handleSaveSection}
          onPreview={() => setView("report-preview")}
          onBack={() => setView("unit-report")}
        />
      </AppShell>
    );
  }

  if (view === "report-preview" && currentUnit) {
    return (
      <AppShell currentView={view} currentUnitId={currentUnitId} onNavigate={navigateTo} onLogout={handleLogout} isAdmin={isAdmin}>
        <ReportPreviewPage unit={currentUnit} report={currentReport} indicatorDefinitions={indicatorDefinitions} onBack={() => setView("unit-report")} />
      </AppShell>
    );
  }

  return <LoginPage onLogin={handleLogin} />;
}
